// Marks the TypeScript files that antlr-ng generates, so the type check and the linter skip them,
// and deletes the interpreter files that the app does not need.
import { readdir, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

const HEADER =
  "// @ts-nocheck\n/* eslint-disable */\n// Generated by antlr-ng from AdvancedSearch.g4. Run `npm run generate:parser` to update.\n";
const directory = process.argv[2];

for (const file of await readdir(directory)) {
  const path = join(directory, file);
  if (file.endsWith(".interp") || file.endsWith(".tokens")) {
    await rm(path);
  } else if (file.endsWith(".ts")) {
    let content = await readFile(path, "utf8");
    // The listener imports antlr4ng interfaces as values. Bundlers need a type-only import.
    if (file.endsWith("Listener.ts")) {
      content = content.replace(
        /^import \{ (.*) \} from "antlr4ng";$/m,
        'import type { $1 } from "antlr4ng";',
      );
    }
    if (!content.startsWith(HEADER)) content = HEADER + content;
    await writeFile(path, content);
  }
}
